layui.define(["jquery","element","table"],function(exports){"use strict";var MOD_NAME="pearCommon",$=layui.jquery,table=layui.table,element=layui.element;var common=new function(){this.checkField=function(obj,field){let data=table.checkStatus(obj.config.id).data;if(data.length===0){return""}let ids="";for(let i=0;i<data.length;i++){ids+=data[i][field]+","}ids=ids.substr(0,ids.length-1);return ids};this.isModile=function(){if($(window).width()<=768){return true}return false};this.submit=function(data,href,table,callback){$.ajax({url:href,data:JSON.stringify(data),dataType:"json",contentType:"application/json",type:"post",success:callback!=null?callback(result):function(result){if(result.success){layer.msg(result.msg,{icon:1,time:1e3},function(){parent.layer.close(parent.layer.getFrameIndex(window.name));parent.layui.table.reload(table)})}else{layer.msg(result.msg,{icon:2,time:1e3})}}})}};exports(MOD_NAME,common)});
